                                             , OUString aObjectCID
                                             , const rtl::Reference<::chart::ChartModel>& xChartModel
                                             , ActionDescriptionProvider::ActionType eActionType )
    : SdrDragMethod( rDrawViewWrapper )
    , m_rDrawViewWrapper(rDrawViewWrapper)
    , m_aObjectCID(std::move(aObjectCID))
