}
OUString DragMethod_Base::GetSdrDragComment() const
{
    return getUndoDescription();
}
PointerStyle DragMethod_Base::GetSdrDragPointer() const
{
    if( IsDraggingPoints() || IsDraggingGluePoints() )
        return PointerStyle::MovePoint;
